@module chrome  src=chrome.lua  loc=790  mode=chunk  self=chrome
@deps cm, ctx, lib

# Shapes
  @shape  chrome = { colour(name, scope?)->u32, pushChromeStyles(), popChromeStyles(), pushChromeWindow(), popChromeWindow(), verticalSeparator(), disabledIf(cond,fn), row(h?,fn), checkbox(label,v), radio(label,active), headingLabel(text), screenPainter()->painter}  @ 3
  @shape  chrome (pickers) = { makeToolbar()->fn(segments), drawPicker(d), libPicker(key, current, excludeOthers?)->items, pickerIsActive()->bool, resetPickerActive(), requestPickerOpen(kind) }  @ 4
  @shape  chrome (shared row primitives) = { rowSelectable(label,sel,flags?)->clicked, treeRow(opts)->{toggled,selected,doubleClicked}, numberStepper(id,value,opts)->changed,value }  @ 5
  @shape  pickerSpec = { kind: string, heading: string?, buttonLabel: string, items: [{label, key, group?=int, current?=bool}], onPick: fn(key), onCancel?: fn(), onCreate?: fn(text), onDelete?: fn(key), placement?: 'above', width?, minWidth?, maxWidth?, flat?: bool }  @ 6
  @shape  palettePaneSpec = { x, y, h, label | {tabs=[{key,label}], activeTab, onTab}, draw = fn(childFocused) }  @ 7
  @shape  toolbarSegment = { id: string, heading?: string (presence = collapsible), render: fn, visible?: fn() -> bool, pickers?: [kind] }  @ 278

# Imports
  @require ImGui = 'imgui'  @ 10
      @contract  one chrome instance per coordinator; threaded into every page  @ 8
      @invariant  colour cache lives on the chrome instance and is invalidated on cm:configChanged  @ 9
  @require painter = 'painter'  @ 11
  @require util = 'util'  @ 12

# Private state
  @state chrome = {}  @ 16
  @state cache = {}  @ 18
  @state NS = { global = true, tracker = true, sampler = true,  @ 45
  @state paintBinder = { colour = chrome.colour }  @ 64
  @state BOX_PAD = 3  @ 179
  @state DROP_ARROW = ' \xe2\x96\xbe'  @ 234
  @state pickerOpenReq = nil  @ 275   -- kind name; consumed by next drawPicker(kind)
  @state pickerOpenSeed = nil  @ 276   -- initial filter text for a request-driven open (type-to-open)
  @state lastToolbarRects = {}  @ 280
  @state toolbarWidths = {}  @ 282
      @invariant  one page draws per frame; cleared at next toolbar() start — no cross-page collision.  @ 281
  @state toolbarLines = 1  @ 283   -- wrapped-row count from the last toolbar() draw
  @state resetPending = false  @ 284
  @state pickerFilter, pickerCursor = {}, {}  @ 412
  @state pickerDeleting = {}  @ 413   -- per kind: the row key whose delete button has been clicked once
  @state pickerActive = false  @ 414   -- frame-scoped: any picker popup live this frame
  @state clearSelCb = nil  @ 417
  @state CREATE = {}  @ 424
  @state DEL_GLYPH = 9  @ 458   -- px across the drawn ×
  @state PALETTE_W, PANE_GAP = 200, 11  @ 644
  @state HEADER_PAD, HEADER_GAP = 8, 4  @ 645
  @state TREE_INDENT, ARROW_GUTTER = 12, 14  @ 743
  @state CHIP_OPEN, CHIP_SHUT = '\xe2\x96\xbe', '\xe2\x96\xb8'  @ 744

# Private functions
  @fn resolve(key)  @ 22-41
      @contract  walks colour aliases (see docs/configManager.md) to a terminal atom; outermost alpha override wins; cycles raise with the resolved chain  @ 21
  @fn scopedKey(name, scope)  @ 47-52
  @fn compactControl(draw)  @ 160-167
      -- Compact (zero-padding) control — checkbox / radio — vertically centered in the
      -- ambient framed-row height; measured from GetFrameHeight, not a fixed nudge.
  @fn setCollapsed(id, on)  @ 293-297
      -- A segment with a summary is collapsible; folded ids persist in config.
  @fn disclosureHeading(text, collapsed)  @ 301-314
      -- headingLabel that toggles: a leading triangle discloses the folded state.
      -- ▸/▾ advance differently, so the triangle gets a fixed cell — no 1px heading shift.
  @fn drawSegment(seg, collapsed)  @ 316-328
  -- Picker (typeahead popup, shared across pages)
  @fn deleteRowButton(kind, key, id, rowLeft, rowW)  @ 462-490
      -- The '?' slot is always reserved, so arming never shifts the ×. Placement has two gotchas
      -- (SameLine's offset base, the Selectable's extended rect) -- see docs/chrome.md § Picker.
  -- Palette pane (shared right-hand pane: arrange / wiring / tracker / sampler)
  @fn paletteTabsHeader(tabs, activeKey, onTab)  @ 672-695
      -- Tabbed header: equal-width cells, active in text ink, rest dimmed (palette.tabInactive).
      -- Dividers run the full header height with a bottom gap; a click fires onTab(key).
  @fn fitLabel(text, maxW)  @ 719-728
      -- Ellipsis-fit to a fixed pane width; no horizontal scroll exists. Private: the
      -- trees fit their own labels, and no caller outside chrome has wanted it.

# Handlers registered
  @handler cm:configChanged()  @ 19

# Public API (chrome.*)
  @api chrome.colour(name, scope)  @ 54-61
  @api chrome.screenPainter()  @ 68
      -- Identity-transform painter over the current window's draw list: screen coords, chrome's
      -- palette. Build one per draw fn — the draw list is captured now, so call it in the target window.
  @api chrome.pushChromeStyles()  @ 70-104
  @api chrome.popChromeStyles()  @ 106-109
  @api chrome.pushChromeWindow()  @ 112-121
      -- Floating surfaces fill with editor.bg (opaque); toolbar.bg is 0.5 alpha and would bleed the grid through.
  @api chrome.popChromeWindow()  @ 123-127
  @api chrome.verticalSeparator()  @ 131-137
      -- reaper-imgui has no Separator(Vertical); draw a 1px vertical rule via the window draw
      -- list and reserve a Dummy slot so SameLine works. see docs/chrome.md § Vertical separator
  @api chrome.disabledIf(cond, fn)  @ 141-145
      -- RAII wrapper for ImGui.BeginDisabled / EndDisabled: dropping the
      -- bracket-match removes a class of mismatched-pop bugs on early return.
  @api chrome.row(h, fn)  @ 149-156
      -- Fixed-height row: run `fn`, then snap the cursor to exactly `h` below the row's
      -- top so subsequent rows land at a deterministic Y regardless of widget heights.
  @api chrome.checkbox(label, value)  @ 169-171
  @api chrome.radio(label, active)  @ 173-175
  @api chrome.numberStepper(id, value, opts)  @ 180-230
  @api chrome.dropdown(id, current, items)  @ 235-260
  @api chrome.headingLabel(text)  @ 264-271
      -- Section label for toolbar segments: bold + uppercase + dimmed so it
      -- reads as a heading and not a control. Caller follows with SameLine.
  @api chrome.resetToolbar()  @ 287
      -- Deferred: the switcher lives in the toolbar, so setActive fires mid-render — clearing
      -- now would unwrap this frame's later segments. Clear at the next toolbar() start instead.
  @api chrome.toolbarRects()  @ 289
  @api chrome.toolbarLineCount()  @ 290
  @api chrome.makeToolbar()  @ 330-406
  @api chrome.requestPickerOpen(kind, seed)  @ 419
  @api chrome.pickerIsActive()  @ 420
  @api chrome.resetPickerActive()  @ 421
  @api chrome.libPicker(key, current, excludeOthers)  @ 428-454
      -- Build the picker-item list for a library-shaped cm key (e.g. 'swings',
      -- 'tempers'); groups, modified badge, excludeOthers — see docs/chrome.md § Picker.
  @api chrome.drawPicker(d)  @ 494-638
      -- Generic typeahead picker. Enter picks the highlighted match; group
      -- separators show only when filter is empty.
  @api chrome.gridWidth(w)  @ 648
      @contract  width of the main pane left of the palette; floors at 120.  @ 647
  @api chrome.paletteHeader(label)  @ 652-668
      -- Hand-drawn header: centred label + 1px divider at headerH; shares HEADER_PAD/HEADER_GAP
      -- with the flanking grid header so dividers align across PANE_GAP. Returns divider screen-y.
  @api chrome.palettePane(spec)  @ 698-715
      @contract  x/y/h are body-window screen coords at the gap's left edge; draw paints the body.  @ 697
  @api chrome.rowSelectable(label, selected, flags)  @ 732-739
      -- Selectable with hover/active highlight suppressed: only the selected row shows
      -- the Col_Header fill. Shared by the tracker palette and the sampler browser/tree.
  @api chrome.treeRow(opts)  @ 751-778
      -- One tree row, sampler-tree style: a draw-list chip in a fixed gutter (never
      -- highlighted), then a selectable label; the row owns its nesting indent.
      @contract  chip toggles; body click selects and toggles a parent; allowDouble suppresses both  @ 748
      @contract  childless rows show blank gutter so labels align across depths  @ 749
      @contract  nesting indent = opts.indent (px) if set, else depth × TREE_INDENT  @ 750
  @api chrome.treeHeading(opts)  @ 782-787
      -- Non-selectable tree heading (fx-section labels, group dividers): a dimmed label.
      @contract  gutter=true aligns text with a same-depth row label, not its chip; else flush indent  @ 781

